function normalizeLinkedInUrl(u){
  if (typeof u !== 'string') return null;

  let x=u.trim();
  if(x==='') return null;

  if(!/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//.test(x)){
    x='https://'+x;
  }

  const m=x.match(
    /^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/([^\/?#]*)([^?#]*)/
  );

  if(!m) return null;

  let host=m[1].toLowerCase();

  if(host.indexOf('@')!==-1){
    return null;
  }

  host=host.replace(/:\d+$/,'');

  if(host.slice(0,4)==='www.'){
    host=host.slice(4);
  }

  let path=m[2]||'';
  path=path.toLowerCase();

  if(
    path.length>1 &&
    path.slice(-1)==='/'
  ){
    path=path.slice(0,-1);
  }

  if(!host){
    return null;
  }

  return host+path;
}


function safeLinkedinPersonUrl(u){

  const n=normalizeLinkedInUrl(u);

  if(n===null){
    return null;
  }

  const i=n.indexOf('/');

  const host=
    i===-1
      ? n
      : n.slice(0,i);

  const path=
    i===-1
      ? ''
      : n.slice(i);

  if(host!=='linkedin.com'){
    return null;
  }

  const pm=
    path.match(/^\/in\/([^\/]+)$/);

  if(
    !pm ||
    pm[1]===''
