    return null;
  }

  return n;
}


function cpSeq(x,y){

  const A=[
    ...String(x)
  ];

  const B=[
    ...String(y)
  ];

  const n=
    Math.min(
      A.length,
      B.length
    );

  for(let i=0;i<n;i++){

    const a=
      A[i].codePointAt(0);

    const b=
      B[i].codePointAt(0);

    if(a!==b){
      return a<b ? -1 : 1;
    }
  }

  return A.length===B.length
    ? 0
    : (
        A.length<B.length
          ? -1
          : 1
      );
}


