function cpSeq(a,b){
  const A=Array.from(String(a)),B=Array.from(String(b)),n=Math.min(A.length,B.length);
  for(let i=0;i<n;i++){
    const x=A[i].codePointAt(0),y=B[i].codePointAt(0);
    if(x!==y) return x<y?-1:1;
  }
