function normPersonUrl(u){
  if(!u) return null;

  let x=String(u).trim().toLowerCase();
  x=x.replace(/^https?:[/][/]/,'').replace(/^www[.]/,'');

  const m=x.match(/^([^/?#]*)([^?#]*)/);
  if(!m) return null;

  let h=m[1];
  h=h.replace(/:[0-9]+$/,'');

  if(h.slice(0,4)==='www.') h=h.slice(4);

  let p=(m[2]||'').toLowerCase();

  if(p.length>1&&p.slice(-1)==='/'){
