function daysInMonth(year, month) {
  return new Date(Date.UTC(year, month, 0)).getUTCDate();
}

function validDay(y, m, d) {
  const dt = new Date(Date.UTC(y, m - 1, d));
  return (
    dt.getUTCFullYear() === y &&
    dt.getUTCMonth() === m - 1 &&
    dt.getUTCDate() === d
  );
}

function parseDateInterval(raw) {
  if (raw === null || raw === undefined || raw === '') {
    return { kind: 'MISSING', interval: null };
  }

  const x = String(raw).trim();

  if (/^(present|current)$/i.test(x)) {
    return { kind: 'PRESENT', interval: null };
  }

  let m = x.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) {
    const y = Number(m[1]);
    const mo = Number(m[2]);
    const d = Number(m[3]);

    if (!validDay(y, mo, d)) {
      return { kind: 'INVALID', interval: null };
    }

    const day = `${m[1]}-${m[2]}-${m[3]}`;
    return {
      kind: 'DATE',
      interval: {
        start: day,
        end: day,
        precision: 'DAY'
      }
    };
  }

  m = x.match(/^(\d{4})-(\d{2})$/);
  if (m) {
    const y = Number(m[1]);
    const mo = Number(m[2]);

    if (mo < 1 || mo > 12) {
      return { kind: 'INVALID', interval: null };
    }

    const last = String(daysInMonth(y, mo)).padStart(2, '0');
    return {
      kind: 'DATE',
      interval: {
        start: `${m[1]}-${m[2]}-01`,
        end: `${m[1]}-${m[2]}-${last}`,
        precision: 'MONTH'
      }
    };
  }

  m = x.match(/^(\d{4})$/);
  if (m) {
    return {
      kind: 'DATE',
      interval: {
        start: `${m[1]}-01-01`,
        end: `${m[1]}-12-31`,
        precision: 'YEAR'
      }
    };
  }

  return { kind: 'INVALID', interval: null };
}

function currentness(role, retrievedAt) {
  const t = Date.parse(retrievedAt);
  if (Number.isNaN(t)) {
    return {
      state: 'UNKNOWN',
      basis: 'INVALID_OR_CONTRADICTORY_ROLE_DATES',
      period: null
    };
  }

  const retrievalDate = new Date(t).toISOString().slice(0, 10);

  const startRaw =
    role.start_date !== undefined ? role.start_date : null;
  const endRaw =
    role.end_date !== undefined ? role.end_date : null;

  const start = parseDateInterval(startRaw);
  const end = parseDateInterval(endRaw);

  const period = {
    start_date_raw: startRaw,
    end_date_raw: endRaw,
    normalized_start_interval: start.interval,
    normalized_end_interval: end.interval,
    structured_current_flag:
      role.current === true
        ? true
        : role.current === false
          ? false
          : null
  };

  // Frozen 2C: malformed date syntax wins before currentness signals.
  if (start.kind === 'INVALID' || end.kind === 'INVALID') {
    return {
      state: 'UNKNOWN',
      basis: 'INVALID_OR_CONTRADICTORY_ROLE_DATES',
      period
    };
  }

  // Impossible chronology.
  if (
    start.interval &&
    end.interval &&
    start.interval.start > end.interval.end
  ) {
    return {
      state: 'UNKNOWN',
      basis: 'INVALID_OR_CONTRADICTORY_ROLE_DATES',
      period
    };
  }

  const explicitProviderCurrent = role.current === true;
  const explicitProviderClosed = role.current === false;
  const explicitPresent = end.kind === 'PRESENT';

  const currentSignal =
    explicitProviderCurrent || explicitPresent;
  const closedSignal = explicitProviderClosed;

  // Explicit signals conflict.
  if (currentSignal && closedSignal) {
    return {
      state: 'UNKNOWN',
      basis: 'CONFLICTING_CURRENTNESS_SIGNALS',
      period
    };
  }

  // Role-start state.
  let startState = 'START_UNKNOWN';

  if (start.interval) {
    if (start.interval.start > retrievalDate) {
      startState = 'FUTURE_START';
    } else if (start.interval.end <= retrievalDate) {
      startState = 'STARTED_CONFIRMED';
    } else {
      startState = 'START_OVERLAPS_RETRIEVAL';
    }
  } // Future start has precedence, and conflicts with CURRENT signal.
  if (startState === 'FUTURE_START') {
    if (currentSignal) {
      return {
        state: 'UNKNOWN',
        basis: 'CONFLICTING_CURRENTNESS_SIGNALS',
        period
      };
    }

