      selected_role:
        selectedRole,

      currentness:
        selectedRole.currentness,

      currentness_basis:
        selectedRole.currentness_basis,

      role_evidence_url:
        selectedRole.role_evidence_url || canonicalUrl,

      retrieved_at:
        pr.retrieved_at || null
    }
  });
}

contacts.sort(
  (a, b) => a.final_rank - b.final_rank
);

return [{
  json: {
    ...s,
    _2e_hr_contacts: contacts
  }
}];

function cpSeq(a, b) {
  const A = Array.from(String(a));
  const B = Array.from(String(b));
  const n = Math.min(A.length, B.length);

  for (let i = 0; i < n; i++) {
    const x = A[i].codePointAt(0);
    const y = B[i].codePointAt(0);

    if (x !== y) {
      return x < y ? -1 : 1;
    }
  }

  return A.length === B.length
    ? 0
    : (A.length < B.length ? -1 : 1);
}


function normPersonUrl(u) {
  if (typeof u !== 'string') {
    return null;
  }

  let x = u.trim().toLowerCase();

  if (!x) {
    return null;
  }

  x = x
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '');

  x = x
    .split('?')[0]
    .split('#')[0]
    .replace(/\/+$/, '');

  if (!/^linkedin\.com\/in\/[^/]+$/.test(x)) {
    return null;
  }

  return x;
}


function canonicalRoleSnapshot(r) {
  if (!r) {
    return null;
  }

  return {
    role_index:
      r.role_index !== undefined
        ? r.role_index
        : null,

    title:
      r.title !== undefined
        ? r.title
        : null,

    organization_snapshot:
      r.organization_snapshot ??
      r.organization ??
      null,

    period:
      r.period ?? {
        start_date_raw:
          r.start_date !== undefined
            ? r.start_date
            : null,

        end_date_raw:
          r.end_date !== undefined
            ? r.end_date
            : null,

        normalized_start_interval: null,
        normalized_end_interval: null,

        structured_current_flag:
          r.current === true
            ? true
            : (
                r.current === false
                  ? false
                  : null
              )
      },

    currentness:
      r.currentness ?? null,

    currentness_basis:
      r.currentness_basis ?? null,

    target_comparison:
      r.target_comparison ??
      r.organization_result ??
      null,

    target_comparison_reason:
      r.target_comparison_reason ??
      r.organization_reason ??
      null,

    role_evidence_url:
      r.role_evidence_url ?? null
  };
}


function canonicalClassifiedRoleSnapshot(r) {
  if (!r) {
    return null;
  }

  return {
    ...canonicalRoleSnapshot(r),

    final_classification:
      r.final_classification ?? null,

    classification_basis:
      r.classification_basis ?? null
