}


function canonicalDiagnostics(
  src,
  fallbackStage,
  fallbackOperation,
  now
) {
  const d = src?.diagnostics || {};

  return {
    stage:
      d.stage ??
      fallbackStage ??
      null,

    adapter_operation:
      d.adapter_operation ??
      fallbackOperation ??
      null,

    attempts:
      d.attempts ??
      src?.attempts ??
      src?.attempt_count ??
      0,

    http_status:
      d.http_status ??
      src?.http_status ??
      null,

    error_code:
      d.error_code ??
      src?.error_code ??
      null,

    normalized_error_class:
      d.normalized_error_class ??
      src?.normalized_error_class ??
      null,

    retrieved_at:
      d.retrieved_at ??
      src?.retrieved_at ??
      now ??
      null,

    warnings:
      Array.isArray(d.warnings)
