    : [];

const pooled =
  Array.isArray(s._2e_pooled)
    ? s._2e_pooled
    : [];

const hydration =
  Array.isArray(s._2e_hydration)
    ? s._2e_hydration
    : [];

const now =
  s._2e_now ?? null;


const poolByKey = new Map();

for (const c of pooled) {
  if (
    c &&
    c.stable_candidate_key != null
