    .slice()
    .sort(
      (a, b) =>
        (a.raw_observation_index ?? 0) -
        (b.raw_observation_index ?? 0)
    );
}


function firstNonNull(arr, field) {
  for (const x of arr) {
    const v = x?.[field];

    if (
      v !== null &&
      v !== undefined &&
      v !== ''
    ) {
      return v;
    }
  }

  return null;
}


function observationProviderRefs(obs) {
  const apolloIds = [];

  for (const o of obs) {
    if (
      o?.source_provider === 'apollo' &&
      o?.source_person_id
    ) {
      if (
        !apolloIds.includes(
          o.source_person_id
        )
      ) {
        apolloIds.push(
          o.source_person_id
        );
      }
    }
  }

  if (apolloIds.length === 1) {
    return {
      apollo_person_id:
        apolloIds[0]
    };
  }

  return {};
}


function commonSafeObservationUrl(obs) {
  const urls = [];

  for (const o of obs) {
    const u =
      normPersonUrl(
        o?.linkedin_url
      );

    if (
      u &&
      !urls.includes(u)
    ) {
      urls.push(u);
    }
  }

  return urls.length === 1
    ? urls[0]
    : null;
}


function baseCandidate(p) {
  const pooledBase =
    p?.stable_candidate_key != null
      ? (
          poolByKey.get(
            p.stable_candidate_key
