function canonicalCandidateUrl(p) {
  const b =
    baseCandidate(p);

  return (
    normPersonUrl(
      b.canonical_url
    ) ??
    normPersonUrl(
      b.requested_profile_url
    ) ??
    normPersonUrl(
      b.linkedin_url
    ) ??
    null
  );
}


function safeDisplayName(p) {
  const b =
    baseCandidate(p);

  const pr =
    b.profile_result || {};

  const canonicalUrl =
    canonicalCandidateUrl(b);

  const observedUrl =
    normPersonUrl(
