  const exactProfileSafe =
    pr.status === 'MATCH' &&
    canonicalUrl !== null &&
    observedUrl === canonicalUrl &&
    b.name_corroboration !== 'CONFLICT';

  const observedName =
    exactProfileSafe &&
    typeof pr.profile?.name === 'string' &&
    pr.profile.name.trim() !== ''
