function findTargetRole(
  p,
  reason
) {
  const roles =
    Array.isArray(p?.roles_org)
      ? p.roles_org
      : [];

  if (p?.selected_role) {
    return p.selected_role;
  }

  if (
    reason ===
    'verified_not_current'
  ) {
    return (
      roles.find(
        r =>
          r.currentness === 'CLOSED' &&
          r.organization_result ===
            'IDENTITY_MATCH'
      ) || null
    );
  }

  if (
    reason ===
    'future_target_role'
  ) {
    return (
      roles.find(
        r =>
          r.currentness === 'FUTURE' &&
          r.organization_result ===
            'IDENTITY_MATCH'
      ) || null
    );
  }

  if (
    reason ===
    'currentness_unresolved'
  ) {
    return (
      roles.find(
        r =>
          r.currentness === 'UNKNOWN' &&
          (
            r.organization_result ===
              'IDENTITY_MATCH' ||
            r.organization_result ===
              'LABEL_MATCH'
          )
      ) || null
    );
  }

  if (
    reason ===
    'target_organization_unresolved'
  ) {
    return (
      roles.find(
        r =>
          r.currentness === 'CURRENT' &&
          (
            r.organization_result ===
              'LABEL_MATCH' ||
            r.organization_result ===
              'INSUFFICIENT'
          )
      ) || null
    );
  }
if (
    reason ===
      'verified_current_target_role' ||
    reason ===
      'non_hr_current_target_role' ||
    reason ===
      'hr_function_unresolved' ||
    reason ===
      'target_role_classification_incomplete'
  ) {
    return (
      roles.find(
        r =>
          r.currentness === 'CURRENT' &&
          r.organization_result ===
            'IDENTITY_MATCH'
      ) || null
    );
  }

  return null;
}


function canonicalTarget(
  p,
  hs
) {
  if (
    p?.target &&
    p.target.organization_snapshot !==
      undefined
  ) {
    return {
      basis:
        p.target.basis ??
        'ACCOUNT_COMPANY',

      organization_snapshot:
        p.target.organization_snapshot ??
        s.account_company ??
        null,

      comparison:
        p.target.comparison ??
        null,

      comparison_reason:
        p.target.comparison_reason ??
        null
    };
  }

  const r =
    findTargetRole(
      p,
      hs?.reason ?? null
    );

  return {
    basis:
      'ACCOUNT_COMPANY',

    organization_snapshot:
      s.account_company ??
      null,

    comparison:
      r?.organization_result ??
      r?.target_comparison ??
      null,

    comparison_reason:
      r?.organization_reason ??
      r?.target_comparison_reason ??
      null
  };
}


function profileDiagnostics(
  p,
  hs
) {
  const pr =
    p?.profile_result || {};

  const merged = {
    ...p,

    normalized_error_class:
      pr.normalized_error_class ??
      p?.normalized_error_class ??
      hs?.diagnostics
        ?.normalized_error_class ??
      null,

    retrieved_at:
      pr.retrieved_at ??
      p?.retrieved_at ??
      now ??
      null
  };

  return canonicalDiagnostics(
    merged,
    'PROFILE_VERIFICATION',
    'profile_by_exact_url',
    now
  );
}


function hydrationDiagnostics(
  p,
  h,
  hs
) {
  const hr =
    h?.hydration_result || {};

  const merged = {
    ...h,

    normalized_error_class:
      hr.normalized_error_class ??
      h?.normalized_error_class ??
      hs?.diagnostics
        ?.normalized_error_class ??
      null,

    retrieved_at:
      h?.retrieved_at ??
      now ??
      null
  };

  return canonicalDiagnostics(
    merged,
    'HYDRATION',
    'person_by_exact_id',
    now
  );
}


function candidateDiagnostics(
  p,
  hs
) {
  if (p?.diagnostics) {
    return canonicalDiagnostics(
      p,
      p.diagnostics.stage ??
        null,
      p.diagnostics.adapter_operation ??
        null,
      now
    );
  }

  const h =
    p?.stable_candidate_key != null
      ? hydrationByKey.get(
          p.stable_candidate_key
        )
      : null;

  const hydrationReasons =
    new Set([
      'candidate_hydration_transient_failure_exhausted',
      'candidate_hydration_invalid_response',
      'no_safe_profile_anchor'
    ]);

  if (
    h &&
    hydrationReasons.has(
      hs?.reason
    )
  ) {
    return hydrationDiagnostics(
      p,
      h,
      hs
    );
  }

  const reconReasons =
    new Set([
      'post_hydration_identity_conflict',
      'post_hydration_duplicate_suppressed',
      'post_hydration_inbound_duplicate_suppressed',
      'inbound_person_identity_conflict'
    ]);

  if (
    reconReasons.has(
      hs?.reason
    ) &&
    !p?.profile_result
  ) {
    return canonicalDiagnostics(
      hs,
      'POST_HYDRATION_RECONCILIATION',
      null,
      now
    );
  }

  if (
    p?.profile_result ||
    p?.requested_profile_url !==
      undefined
  ) {
    return profileDiagnostics(
      p,
      hs
    );
  }

  if (h) {
    return hydrationDiagnostics(
      p,
      h,
      hs
    );
  }

  return canonicalDiagnostics(
    hs,
    'PRE_VERIFICATION',
    null,
    now
  );
}


function canonicalEvidence(p) {
  const canonicalUrl =
    canonicalCandidateUrl(p);

  const roles =
    Array.isArray(p?.roles_org)
      ? p.roles_org
      : []; 
  const verifiedIndexes =
    new Set(
      (
        Array.isArray(
          p?.verified_current_target_roles
        )
          ? p.verified_current_target_roles
          : []
      )
        .map(
          x =>
            typeof x === 'object'
              ? x.role_index
              : x
        )
        .filter(
          x =>
            x !== null &&
            x !== undefined
        )
    );

  const selectedRole =
    p?.selected_role
      ? canonicalClassifiedRoleSnapshot(
          p.selected_role
        )
      : null;

  return {
    profile_url:
      canonicalUrl,

    roles_considered:
      roles.map(
        canonicalRoleSnapshot
      ),

    verified_current_target_roles:
      roles
        .filter(
          r =>
            verifiedIndexes.has(
              r.role_index
            )
        )
        .map(
          canonicalRoleSnapshot
        ),

    classified_current_target_roles:
      (
        Array.isArray(
          p?.classified_current_target_roles
        )
          ? p.classified_current_target_roles
          : []
      ).map(
        canonicalClassifiedRoleSnapshot
      ),

    selected_role:
      selectedRole,

    role_evidence_url:
      selectedRole
        ?.role_evidence_url ??
      null
  };
}


/*
 * 1. PRE_VERIFICATION_TERMINAL
 *
 * These candidates are outside _2e_profiles but
 * MUST still be present in flagged_hr_contacts.
