    isDiscoveryConflict
      ? null
      : commonSafeObservationUrl(
          obs
        );

  const providerRefs =
    isDiscoveryConflict
      ? {}
      : observationProviderRefs(
          obs
        );

  flagged.push({
    stable_candidate_key:
      t.stable_candidate_key ??
      null,

    name,

    linkedin_url:
      linkedinUrl,

    provider_refs:
      providerRefs,

    audit_observation_keys:
      Array.isArray(
        t.audit_observation_keys
      )
        ? t.audit_observation_keys
        : [],

    conflict_group_key:
      t.conflict_group_key ??
      null,

    provider_reported_title:
      firstNonNull(
        obs,
        'provider_reported_title'
      ),

    discovery_rank:
      null,

    eligible_rank:
      null,

    completion_class:
      t.completion_class ??
      'BUSINESS_COMPLETE',

    employment_status:
      t.employment_status ??
      'UNVERIFIED',

    hr_selection_status:
      t.hr_selection_status ??
      'NOT_APPLICABLE',

    flag_reason:
      t.reason ??
      null,

    target: {
      basis:
        'ACCOUNT_COMPANY',

      organization_snapshot:
        s.account_company ??
        null,

      comparison:
        null,

      comparison_reason:
        null
    },

    evidence: {
      profile_url:
        linkedinUrl,

      roles_considered:
        [],

      verified_current_target_roles:
        [],

      classified_current_target_roles:
        [],

      selected_role:
        null,

      role_evidence_url:
        null
    },

    diagnostics:
      canonicalDiagnostics(
        t,
        'PRE_VERIFICATION',
        null,
        now
