}


/*
 * 2. Verification-pool candidates which did
 * not enter final hr_contacts.
 */
for (
  const raw of (
    Array.isArray(s._2e_profiles)
      ? s._2e_profiles
      : []
  )
) {
  const p =
    baseCandidate(raw);

  /*
   * Already emitted by Build HR Contacts.
   */
  if (
    p.final_rank !== null &&
    p.final_rank !== undefined
  ) {
    continue;
  }

  const hs =
    outcomeFor(p);

  /*
   * A candidate without a terminal verification
   * outcome has nothing to persist here.
   */
  if (
    !hs ||
    !hs.completion_class
  ) {
    continue;
  }
  /*
   * Phase A inbound duplicate suppression
   * is audit-only and MUST NOT be emitted
   * as flagged_hr_contact.
