  if (
    hs.reason ===
    'post_hydration_inbound_duplicate_suppressed'
  ) {
    continue;
  }

  const isRankOut =
    p.eligible_rank !== null &&
    p.eligible_rank !== undefined &&
    p.eligible_rank > MAXF &&
    hs.completion_class ===
      'BUSINESS_COMPLETE' &&
    hs.employment_status ===
      'VERIFIED_CURRENT' &&
    hs.hr_selection_status ===
      'ELIGIBLE';

  flagged.push({
    stable_candidate_key:
      p.stable_candidate_key ??
      null,

    name:
      safeDisplayName(p),

    /*
     * Do NOT use observed_profile_url here.
     * This preserves the Test 17 exact-profile
     * identity-lock fix.
     */
    linkedin_url:
      canonicalCandidateUrl(p),

    provider_refs:
      p.provider_refs || {},

    audit_observation_keys:
      Array.isArray(
        p.audit_observation_keys
      )
        ? p.audit_observation_keys
        : [],

    conflict_group_key:
      p.conflict_group_key ??
      null,

    provider_reported_title:
      p.provider_reported_title ??
      null,

    discovery_rank:
      p.discovery_rank ??
      null,

    eligible_rank:
      p.eligible_rank ??
      null,

    completion_class:
      hs.completion_class ??
      null,

    employment_status:
      hs.employment_status ??
      null,

    hr_selection_status:
      hs.hr_selection_status ??
      null,

    flag_reason:
      isRankOut
        ? 'not_selected_due_to_rank'
        : (
            hs.reason ??
            null
          ),

    target:
      canonicalTarget(
        p,
        hs
      ),

    evidence:
      canonicalEvidence(p),

    diagnostics:
      candidateDiagnostics(
        p,
        hs
      )
  });
}


/*
 * §28 canonical persistence ordering.
 */
flagged.sort(
  (a, b) => {
    const aNull =
      a.discovery_rank === null ||
      a.discovery_rank === undefined;

    const bNull =
      b.discovery_rank === null ||
      b.discovery_rank === undefined;

    if (
      aNull &&
      bNull
    ) {
      const ka =
        a.stable_candidate_key ??
        a.conflict_group_key ??
        a.audit_observation_keys?.[0] ??
        '';

      const kb =
        b.stable_candidate_key ??
        b.conflict_group_key ??
        b.audit_observation_keys?.[0] ??
        '';

      return cpSeq(
        ka,
        kb
      );
    }

    if (aNull) {
      return -1;
    }

    if (bNull) {
      return 1;
    }

    if (
      a.discovery_rank !==
      b.discovery_rank
    ) {
      return (
        a.discovery_rank -
        b.discovery_rank
      );
    }

    return cpSeq(
      a.stable_candidate_key ??
        '',
      b.stable_candidate_key ??
        ''
    );
  }
);


return [{
  json: {
