  }
}];

const s=$input.first().json||{}; if(s._2e_fail) return [{json:s}];
const out=(s._2e_profiles||[]).map(p=>{
  const hs=p.hr_selection||p.candidate_outcome||{};
  const cc=hs.completion_class||null;
  return {...p, _dest_class:cc};
});
const poolKeys=new Set((s._2e_pooled||[]).map(c=>c.stable_candidate_key));
const pool=out.filter(p=>poolKeys.has(p.stable_candidate_key));
let bc=0,tg=0,ne=0,ve=0;
for(const p of pool){
  if(p._dest_class==='BUSINESS_COMPLETE') bc++;
  else if(p._dest_class==='TECHNICAL_GAP') tg++;
  else if(p._dest_class==='NOT_EVALUATED') ne++;
