}
const poolCount=pool.length;
const selGap=!!s._2e_selection_gap;
let status;
if(poolCount===0) status='NOT_APPLICABLE';
else if(tg===0&&ne===0&&!selGap) status='COMPLETE';
else if(bc>0) status='PARTIAL';
else status='FAILED';
return [{json:{...s,_2e_verification:{status:status,business_complete_count:bc,technical_gap_count:tg,
 not_evaluated_count:ne,verified_eligible_count:ve,final_contact_count:(s._2e_hr_contacts||[]).length,
 verification_pool_count:poolCount,selection_technical_gap:selGap}}}];

const s=$input.first().json||{}; if(s._2e_fail) return [{json:s}];
const disc=s._2e_discovery||{}; const v=s._2e_verification||{};
const contacts=(s._2e_hr_contacts||[]).length;
let st;
if(disc.status==='FAILED'||disc.completeness==='FAILED') st='failed';
else if(disc.status==='EMPTY'&&disc.completeness==='COMPLETE') st='empty';
else if(disc.status==='SUCCESS'&&disc.completeness==='PARTIAL') st='failed';
else if(disc.status==='SUCCESS'&&disc.completeness==='COMPLETE'){
  if(v.verification_pool_count===0&&!v.selection_technical_gap) st='empty';
  else if(v.status==='COMPLETE'&&contacts>0) st='success';
  else if(v.status==='COMPLETE'&&contacts===0) st='empty';
  else st='failed';
} else st='failed';
return [{json:{...s,_2e_hr_discovery_status:st}}];

