    raw_provider_count:d.raw_provider_count||0,canonical_observation_count:obs.length,discovery_adapter_rejection_count:rej.length,
    outside_discovery_fetch_cap_count:cap.length,attempts:(d.diagnostics||{}).attempts||0,http_status:(d.diagnostics||{}).http_status||null,
    error_code:(d.diagnostics||{}).error_code||null,retrieved_at:(d.diagnostics||{}).retrieved_at||null},
  discovery_observations:obs,
