  service_states:{hydration:s._2e_hydration_service||{state:'AVAILABLE',breaker_key:null,last_logical_call_index:null,consecutive_transient_exhaustions:0},
    profile_retrieval:s._2e_profile_service||{state:'AVAILABLE',breaker_key:null,last_logical_call_index:null,consecutive_transient_exhaustions:0},
