      breaker_key:s._2e_mode==='DETERMINISTIC_RULES'?null:(s._2e_endpoints||{}).TITLE_CLASSIFICATION,
      last_logical_call_index:(s._2e_title_lci||0)||null,consecutive_transient_exhaustions:s._2e_title_streak||0}},
  circuit_breakers:(s._2e_circuit_events||[]).slice()
