// ===========================================================================
// 2. VERIFICATION-POOL DENOMINATOR
// ===========================================================================
//
// Verification denominator is the ORIGINAL admitted bounded pool.
//
// It must not shrink merely because a candidate:
//
// - terminated during hydration;
// - terminated during reconciliation;
// - received no profile call;
// - became audit-only after late inbound duplicate detection.
// ===========================================================================

const pooled=s._2e_pooled||[];
const profiles=s._2e_profiles||[];

const pooledKeys=new Set();


for(const c of pooled){

  if(
    !c ||
    !c.stable_candidate_key
  ){
    return fail(
      s,
      '§23: verification-pool candidate has null stable_candidate_key'
    );
  }


  if(pooledKeys.has(c.stable_candidate_key)){

    return fail(
      s,
      '§23: duplicate stable_candidate_key inside verification pool'
    );
  }


  pooledKeys.add(c.stable_candidate_key);
}  // Evidence denominator must equal original admitted pool.

if(
  !eq(
    cp.verification_pool_count,
    pooled.length
  )
){
  return fail(
    s,
    '§23: evidence verification_pool_count != admitted verification pool size'
  );
}


// Reconciliation must retain the same denominator.

if(
  rec.verification_pool_count!==undefined &&
  rec.verification_pool_count!==null &&
  !eq(
    rec.verification_pool_count,
    pooled.length
  )
){
  return fail(
    s,
    '§23: reconciliation verification_pool_count != admitted verification pool size'
  );
}


// _2e_profiles is now the canonical downstream registry
// for every admitted verification-pool candidate.

if(
  !eq(
    profiles.length,
    pooled.length
  )
){
  return fail(
    s,
    '§23: downstream candidate registry size != verification pool size'
  );
}


const profileKeys=new Set();


for(const p of profiles){

  if(
    !p ||
    !p.stable_candidate_key
  ){
    return fail(
      s,
      '§23: downstream verification candidate has null stable_candidate_key'
    );
  }


  if(!pooledKeys.has(p.stable_candidate_key)){

    return fail(
      s,
      '§23: downstream candidate is not a member of verification pool'
    );
  }


  if(profileKeys.has(p.stable_candidate_key)){

    return fail(
      s,
      '§23: verification-pool candidate represented more than once downstream'
    );
  }


  profileKeys.add(p.stable_candidate_key);
}


for(const key of pooledKeys){

  if(!profileKeys.has(key)){

    return fail(
      s,
      '§23: verification-pool candidate disappeared downstream: '+key
    );
  }
}


// ===========================================================================
