// ===========================================================================
// 5. §27.2 HR CONTACT INVARIANTS
// ===========================================================================

const seenUrl={};
const seenRank={};


for(const c of (s._2e_hr_contacts||[])){

  if(!c.stable_candidate_key){

    return fail(
      s,
      '§27.2: contact has null stable_candidate_key'
    );
  }


  if(
    c.function==='UNKNOWN' ||
    c.function==='GENERAL_MANAGEMENT' ||
    c.function==='OTHER'
  ){

    return fail(
      s,
      '§27.2: contact has non-HR function'
    );
  } const completionClass=
    c.verification &&
    c.verification.completion_class
      ? c.verification.completion_class
      : c.completion_class;


  if(completionClass!=='BUSINESS_COMPLETE'){

    return fail(
      s,
      '§27.2: contact completion_class != BUSINESS_COMPLETE'
    );
  }


  if(
    !c.target ||
    c.target.comparison!=='IDENTITY_MATCH'
  ){

    return fail(
      s,
      '§27.2: contact target comparison != IDENTITY_MATCH'
    );
  }


  if(
    c.verification &&
    c.verification.target_comparison &&
    c.verification.target_comparison!=='IDENTITY_MATCH'
  ){

    return fail(
      s,
      '§27.2: contact verification.target_comparison != IDENTITY_MATCH'
    );
  }


  if(
    c.verification &&
    c.verification.employment_status!=='VERIFIED_CURRENT'
  ){

    return fail(
      s,
      '§27.2: contact employment_status != VERIFIED_CURRENT'
    );
  }


  if(
    c.verification &&
    c.verification.hr_selection_status!=='ELIGIBLE'
  ){

    return fail(
      s,
      '§27.2: contact hr_selection_status != ELIGIBLE'
    );
  }


  if(
    !(
      c.final_rank>=1 &&
      c.final_rank<=3
    )
  ){

    return fail(
      s,
      '§27.2: final_rank out of 1..3'
    );
