  if(
    [
      'VERIFIED_TITLE_CLASSIFICATION',
      'PROVISIONAL_REUSED_EXACT_NORMALIZED_TITLE',
      'CACHED_EXACT_NORMALIZED_TITLE'
    ].indexOf(c.classification_basis)===-1
  ){

    return fail(
      s,
      '§27.2: invalid classification_basis'
    );
  }


  if(!c.linkedin_url){

    return fail(
      s,
      '§27.2: contact has null LinkedIn URL'
    );
  }


  if(seenUrl[c.linkedin_url]){

    return fail(
      s,
      '§27.2: duplicate normalized LinkedIn URL across contacts'
    );
  }


  seenUrl[c.linkedin_url]=1;


  if(seenRank[c.final_rank]){

    return fail(
      s,
      '§27.2: duplicate final_rank'
    );
  }


  seenRank[c.final_rank]=1;
}


// final_rank must be contiguous 1..N

const contactRanks=
  (s._2e_hr_contacts||[])
    .map(c=>c.final_rank)
    .slice()
    .sort((a,b)=>a-b);


for(let i=0;i<contactRanks.length;i++){

  if(contactRanks[i]!==i+1){

    return fail(
      s,
      '§27.2: final_rank is not contiguous'
    );
  }
}


// ===========================================================================
// 6. CONTACT / FLAGGED MUTUAL EXCLUSIVITY
// ===========================================================================

const contactKeys=new Set();

for(const c of (s._2e_hr_contacts||[])){

  if(c.stable_candidate_key){
    contactKeys.add(c.stable_candidate_key);
  }
}


for(const f of (s._2e_flagged||[])){

  if(
    f.stable_candidate_key &&
    contactKeys.has(f.stable_candidate_key)
  ){

    return fail(
      s,
      '§51: candidate appears in both hr_contacts and flagged_hr_contacts'
    );
  }
}


// ===========================================================================
// 7. §21 AUDIT-ONLY MEMBERSHIP
// ===========================================================================
//
// Audit-only categories:
//
// - PRE-VERIFICATION INBOUND_PERSON_DUPLICATE
// - OUTSIDE_VERIFICATION_CAP
// - malformed raw observation
// - POST_HYDRATION INBOUND_PERSON_DUPLICATE_SUPPRESSION
//
// IMPORTANT:
// _2e_pre_terminal is NOT audit-only.
//
// PRE_VERIFICATION:
//   inbound_person_identity_conflict,
//   no_safe_profile_anchor,
//   discovery_identity_conflict
//
// are canonical flagged outcomes.
// ===========================================================================

const auditOnlyStableKeys=new Set();


// Pre-verification canonical inbound duplicates.

for(const e of (s._2e_excluded||[])){

  if(e && e.stable_candidate_key){
    auditOnlyStableKeys.add(
      e.stable_candidate_key
    );
  }
}


// Outside bounded verification cap.

for(const e of (s._2e_pool_exclusions||[])){

  if(e && e.stable_candidate_key){
    auditOnlyStableKeys.add(
      e.stable_candidate_key
    );
  }
}


// POST_HYDRATION Phase A:
// ONLY inbound duplicate suppression is audit-only.
// Inbound identity conflict MUST be flagged. 

const phaseA=
  (s._2e_recon || {}).phase_a || {};


for(const key of Object.keys(phaseA)){

  const disp=phaseA[key]||{};

  if(
    disp.type===
    'INBOUND_PERSON_DUPLICATE_SUPPRESSION'
  ){

    auditOnlyStableKeys.add(key);
  }
}


// No audit-only stable key may appear in flagged_hr_contacts.

for(const f of (s._2e_flagged||[])){

  if(
    f.stable_candidate_key &&
    auditOnlyStableKeys.has(
      f.stable_candidate_key
    )
  ){

    return fail(
      s,
      '§21: audit-only candidate appeared in flagged_hr_contacts'
    );
  }
}


// ===========================================================================
// 8. §21 REQUIRED FLAGGED MEMBERSHIP
// ===========================================================================

const flaggedStableKeys=new Set();

const flaggedConflictKeys=new Set();

const flaggedAuditKeys=new Set();


for(const f of (s._2e_flagged||[])){

  if(f.stable_candidate_key){
    flaggedStableKeys.add(
      f.stable_candidate_key
    );
  }


  if(f.conflict_group_key){
    flaggedConflictKeys.add(
      f.conflict_group_key
    );
  }


  for(const k of (f.audit_observation_keys||[])){
    flaggedAuditKeys.add(k);
  }
}


// ---------------------------------------------------------------------------
// 8A. Every non-contact verification-pool result must be flagged
//     unless explicitly audit-only.
// ---------------------------------------------------------------------------

for(const p of profiles){

  const key=p.stable_candidate_key;


  if(contactKeys.has(key)){
    continue;
  }


  if(p._2e_audit_only===true){

    if(flaggedStableKeys.has(key)){

      return fail(
        s,
        '§21: _2e_audit_only reconciliation candidate was flagged'
      );
    }

    continue;
  }


  if(!flaggedStableKeys.has(key)){

    return fail(
      s,
      '§21: canonical verification-pool result missing from flagged_hr_contacts: '+key
    );
  }
}


// ---------------------------------------------------------------------------
// 8B. Every PRE_VERIFICATION_TERMINAL result must be flagged.
// ---------------------------------------------------------------------------

for(const t of (s._2e_pre_terminal||[])){

  if(!t){
    continue;
  }


  if(t.stable_candidate_key){

    if(
      !flaggedStableKeys.has(
        t.stable_candidate_key
      )
    ){

      return fail(
        s,
        '§21: pre-verification terminal candidate missing from flagged_hr_contacts'
      );
    }

    continue;
  }


  if(t.conflict_group_key){

    if(
      !flaggedConflictKeys.has(
        t.conflict_group_key
      )
    ){

      return fail(
        s,
        '§21: pre-verification conflict group missing from flagged_hr_contacts'
      );
    }

    continue;
  }


  const aoks=
    t.audit_observation_keys||[];


  if(!aoks.length){

    return fail(
      s,
      '§21: pre-verification terminal result has no durable audit identity'
    );
  }


  const represented=
    aoks.some(
      k=>flaggedAuditKeys.has(k)
    );


  if(!represented){

    return fail(
      s,
      '§21: pre-verification terminal audit result missing from flagged_hr_contacts'
    );
  }
}


// ===========================================================================
// 9. POST-HYDRATION RECONCILIATION MEMBERSHIP
// ===========================================================================
//
// Phase A:
//
// INBOUND_PERSON_IDENTITY_CONFLICT
//     -> flagged
//
// INBOUND_PERSON_DUPLICATE_SUPPRESSION
//     -> audit only
//
// Phase B:
//
// CROSS_CANDIDATE_IDENTITY_CONFLICT
//     -> flagged
//
// DUPLICATE_SUPPRESSION suppressed member
//     -> flagged
// ===========================================================================


// Phase A

for(const key of Object.keys(phaseA)){

  const disp=phaseA[key]||{};


  if(
    disp.type===
    'INBOUND_PERSON_DUPLICATE_SUPPRESSION'
  ){

    if(flaggedStableKeys.has(key)){

      return fail(
        s,
        '§21: post-hydration inbound duplicate suppression must be audit-only'
      );
    } } else if(
    disp.type===
    'INBOUND_PERSON_IDENTITY_CONFLICT'
  ){

    if(!flaggedStableKeys.has(key)){

      return fail(
        s,
        '§21: post-hydration inbound identity conflict must be flagged'
      );
    }

  } else {

    return fail(
      s,
      '§10.3: unknown Phase A reconciliation outcome'
    );
  }
}


// Phase B

const phaseB=
  (s._2e_recon|| {}).phase_b || {};


for(const key of Object.keys(phaseB)){

  const disp=phaseB[key]||{};


  if(
    disp.type===
    'CROSS_CANDIDATE_IDENTITY_CONFLICT'
  ){

    if(!flaggedStableKeys.has(key)){

      return fail(
        s,
        '§21: post-hydration cross-candidate identity conflict must be flagged'
      );
    }

  } else if(
    disp.type===
    'DUPLICATE_SUPPRESSION'
  ){

    if(!flaggedStableKeys.has(key)){

      return fail(
        s,
        '§21: post-hydration duplicate suppression must be flagged'
      );
    }

  } else {

    return fail(
      s,
      '§10.3: unknown Phase B reconciliation outcome'
    );
  }
}


// ===========================================================================
// 10. FINAL AUDIT-ONLY MARKER CONSISTENCY
// ===========================================================================
//
// _2e_audit_only=true is currently legal only for the frozen
// post_hydration_inbound_duplicate_suppressed outcome.
// ===========================================================================

for(const p of profiles){

  if(p._2e_audit_only!==true){
    continue;
  }


  const r=
    p.candidate_outcome||{};


  if(
    r.reason!==
    'post_hydration_inbound_duplicate_suppressed'
  ){

    return fail(
      s,
      '§21: unexpected _2e_audit_only candidate outcome'
    );
  }


  const disp=
    phaseA[p.stable_candidate_key]||null;


  if(
    !disp ||
    disp.type!==
    'INBOUND_PERSON_DUPLICATE_SUPPRESSION'
  ){

    return fail(
      s,
      '§21: _2e_audit_only marker lacks canonical Phase A duplicate suppression'
    );
  }
}


// ===========================================================================
// PASS
// ===========================================================================

return [{
  json:{
    ...s,
    _2e_invariants_ok:true
  }
}];

const s=$input.first().json||{}; if(s._2e_fail) return [{json:s}];
const o={};
for(const k of Object.keys(s)){ if(k.indexOf('_2e')!==0 && k!=='l2e_config') o[k]=s[k]; }
o.hr_discovery_status=s._2e_hr_discovery_status||null;
o.hr_contacts=s._2e_hr_contacts||[];
o.flagged_hr_contacts=s._2e_flagged||[];
o.hr_discovery_evidence=s._2e_evidence||null;
return [{json:o}];
